-- Accepted editorial batch: ten independently sourced public-domain song ideas.
WITH ideas (title, full_story, hero_pov, central_conflict, emotional_arc, ending_direction, hook_direction, genres, moods, energy, themes, generator_brief, generator_story, sort_order) AS (
  VALUES
  ('Море нас услышит','Во время тяжёлого шторма команда теряет уверенность, пока дочь капитана не возвращает отцу способность действовать и доверять людям рядом.','От первого лица, капитан.','Паника перед стихией против доверия к близким и команде.','От тревоги к надежде.','К рассвету корабль входит в гавань, а отец слышит в дочери не страх, а опору.','Тихий голос, который слышно сквозь море.',ARRAY['Эпик-рок'],ARRAY['Тревога','Надежда'],'Высокая',ARRAY['Семья','Море'],'Эпик-рок о капитане, которому голос дочери помогает вывести команду из шторма.','Во время шторма дочь возвращает отцу и команде спокойствие, и корабль идёт к берегу.',131),
  ('Шаг до крыльца','Робкий парень долго не может заговорить с девушкой, но обычный зимний вечер даёт ему смелость сделать один честный шаг навстречу.','От первого лица, парень.','Страх быть отвергнутым против желания быть услышанным.','От смущения к нежности.','Он не прячется за окном, а стучит в дверь и начинает разговор.','Следы на свежем снегу у крыльца.',ARRAY['Кантри'],ARRAY['Нежность'],'Средняя',ARRAY['Любовь','Дом'],'Кантри о робком признании, которое начинается с одного шага к освещённому крыльцу.','Парень перестаёт наблюдать издалека и честно говорит девушке о чувствах.',132),
  ('Сначала спроси, умеешь ли','Самоуверенный герой покупает велосипед, уверенный, что справится без подготовки, но неуправляемая поездка учит его смеяться над собой и просить помощи.','От первого лица, герой.','Показная компетентность против реального умения и готовности учиться.','От бравады к самоиронии.','Он возвращается к друзьям и начинает заново, уже без хвастовства.','Велосипед, который мчится быстрее уверенности.',ARRAY['Кантри'],ARRAY['Ирония'],'Высокая',ARRAY['Работа','Дружба'],'Ироничное кантри о человеке, который превращает провал в первый честный урок.','Герой уверен, что умеет всё, но падение учит его сначала спросить и только потом ехать.',133),
  ('Спуск без свидетелей','Молодого всадника считают слишком неопытным для трудной погони, но он вместе со своим пони выбирает опасный путь и возвращает потерянный табун.','От первого лица, молодой всадник.','Чужое недоверие против собственного знания и верности животного.','От сомнения к признанию.','Он возвращается не ради славы, а чтобы поблагодарить пони за общий риск.','Копыта, выбивающие искры на каменном склоне.',ARRAY['Эпик-рок'],ARRAY['Вдохновение'],'Высокая',ARRAY['животные','Риск'],'Эпик-рок о всаднике и пони, которым доверяют только после невозможного спуска.','Недооценённый всадник вместе с пони проходит опасный склон и возвращает табун.',134),
  ('Всё сразу','Мастер годами строит безупречную повозку, где каждая деталь рассчитана одинаково, но в самый обычный день вся конструкция распадается разом.','От первого лица, мастер.','Культ идеальности против живой непредсказуемости мира.','От гордости к освобождающему смеху.','Он перестаёт чинить образ совершенства и делает вещь, которой можно пользоваться и ошибаться.','Повозка, рассыпающаяся в один миг.',ARRAY['Электропоп'],ARRAY['Ирония'],'Средняя',ARRAY['Работа','Самопринятие'],'Электропоп о мастере, который после идеального провала разрешает себе быть живым.','Идеальная повозка разваливается сразу, и мастер учится ценить не безупречность, а жизнь.',135),
  ('Перчатка не доказательство','Герой выполняет опасное требование любимой, но понимает, что любовь не может строиться на риске ради чужого одобрения.','От первого лица, герой.','Тщеславная проверка чувств против уважения к себе и партнёру.','От азарта к ясной границе.','Он возвращает символ испытания и выбирает отношения без требований доказать любовь.','Перчатка, возвращённая без поклона.',ARRAY['Соул'],ARRAY['Решимость'],'Средняя',ARRAY['Любовь','Самоценность'],'Соул о человеке, который перестаёт доказывать любовь опасными поступками.','Герой проходит рискованное испытание, но выбирает не жить по правилам чужого тщеславия.',136),
  ('Колокол под водой','Человек убирает предупреждающий колокол с опасного места ради выгоды, а затем понимает, что поставил под риск чужие жизни, и пытается всё исправить.','От первого лица, герой.','Личная выгода против безопасности незнакомых людей.','От цинизма к вине и ответственности.','Он возвращает предупреждение до того, как в опасность попадёт чужой корабль.','Колокол, который слышен даже под водой.',ARRAY['Техно'],ARRAY['Напряжение'],'Высокая',ARRAY['Море','спасение'],'Техно о цене саботажа и решении вернуть людям сигнал опасности.','Герой убирает морской колокол ради выгоды, но возвращает его, поняв цену чужой безопасности.',137),
  ('Плыви, пока спят','Молодой рыбак ночью переплывает реку ради тайной встречи, но оба понимают: чувства не должны превращать близкого человека в постоянный риск.','От первого лица, молодой рыбак.','Желание быть рядом против опасности тайных встреч и страха быть раскрытыми.','От игры к тревоге и облегчению.','Они договариваются встретиться днём и говорить друг с другом открыто.','Лунная вода между двумя берегами.',ARRAY['Регги'],ARRAY['Романтика'],'Средняя',ARRAY['Любовь','Море'],'Регги о ночном заплыве к любви, который приводит к честному разговору.','Рыбак переплывает реку ради тайной встречи, но влюблённые выбирают близость без опасной игры.',138),
  ('Экспедиция из ниоткуда','Разношёрстная команда отправляется искать нечто, чего никто не видел; страхи и нелепые привычки мешают, пока люди не учатся быть настоящей командой.','От первого лица, организатор команды.','Абсурдность общей цели против потребности держаться вместе.','От хаоса к доверию и открытому финалу.','Они не находят готового ответа, но понимают, что сами стали тем, ради чего вышли в путь.','Карта без единого ориентира.',ARRAY['Альтернатива'],ARRAY['Мечтательность'],'Средняя',ARRAY['Команда','Поиск себя'],'Альтернатива о команде, которая отправляется за невозможным и находит друг друга.','Разные люди ищут несуществующее существо и постепенно становятся настоящей командой.',139),
  ('Своя минута','Ослика постоянно считают смешным и ненужным, но он хранит память о моменте, когда именно его спокойный шаг оказался важен для всех вокруг.','От первого лица, ослик.','Насмешка окружающих против внутреннего достоинства.','От унижения к тихой силе.','Он перестаёт ждать одобрения и идёт своим путём, зная собственную ценность.','Длинные уши на фоне чужих аплодисментов.',ARRAY['Блюз'],ARRAY['Сила'],'Средняя',ARRAY['животные','Самоценность'],'Блюз о животном, которое находит достоинство не в чужом смехе, а в собственной памяти о важном пути.','Ослик, которого высмеивают, помнит момент, когда его путь был нужен всем, и обретает силу.',140)
)
INSERT INTO public.song_ideas (title, full_story, hero_pov, central_conflict, emotional_arc, ending_direction, hook_direction, genres, moods, energy, themes, generator_brief, generator_story, is_published, sort_order)
SELECT title, full_story, hero_pov, central_conflict, emotional_arc, ending_direction, hook_direction, genres, moods, energy, themes, generator_brief, generator_story, true, sort_order
FROM ideas;

WITH sources (title, original_key, author_name, original_title, original_language, origin_country, original_year, source_url, rights_check, music_adaptations, source_synopsis, main_image, editor_note) AS (
  VALUES
  ('Море нас услышит','james-thomas-fields|ballad-of-the-tempest','James Thomas Fields','Ballad of the Tempest','English','USA',1849,'https://en.wikisource.org/wiki/Ballad_of_the_Tempest','Автор умер в 1881 году; произведение 1849 года и авторская страница Wikisource подтверждают public domain.','["Ruth Morris Gray — Ballad of the Tempest, SATB (2006)"]','Во время морской бури дочь капитана возвращает ему веру и спокойствие.','Тихий голос в шторме','Не использовать религиозные формулировки и строки оригинала.'),
  ('Шаг до крыльца','james-russell-lowell|the-courtin','James Russell Lowell','The Courtin’','English','USA',1848,'https://library.si.edu/digital-library/book/courti00lowe','Автор умер в 1891 году; Smithsonian отмечает издание как public domain / no copyright in the United States.','[]','Робкий Зекл приходит к Халди зимним вечером и находит смелость для ухаживания.','Следы у освещённого крыльца','Используем только ситуацию робкого признания, без диалектных строк.'),
  ('Сначала спроси, умеешь ли','a-b-paterson|mulga-bills-bicycle','A. B. Paterson','Mulga Bill’s Bicycle','English','Australia',1896,'https://en.wikisource.org/wiki/Mulga_Bill%27s_Bicycle','Wikisource указывает public domain в Австралии и США; автор умер в 1941 году.','[]','Хвастливый герой покупает велосипед, теряет контроль и признаёт, что переоценил себя.','Неуправляемый велосипед','Не переносить комические формулы и строки оригинала.'),
  ('Спуск без свидетелей','a-b-paterson|the-man-from-snowy-river','A. B. Paterson','The Man from Snowy River','English','Australia',1895,'https://en.wikisource.org/wiki/The_Man_From_Snowy_River','Первое издание и авторское право подтверждены PD-сканом Wikisource; автор умер в 1941 году.','[]','Недооценённый молодой всадник на горном пони возвращает табун после опасного спуска.','Копыта на каменном склоне','Не копировать описание погони и топонимы оригинала.'),
  ('Всё сразу','oliver-wendell-holmes|the-deacons-masterpiece','Oliver Wendell Holmes Sr.','The Deacon’s Masterpiece','English','USA',1858,'https://en.wikisource.org/wiki/The_Deacon%27s_Masterpiece','Wikisource прямо отмечает произведение как public domain worldwide; автор умер в 1894 году.','[]','Идеально сбалансированная повозка служит сто лет, а затем разваливается целиком.','Повозка, рассыпающаяся разом','Берём только конфликт идеальности и непредсказуемости.'),
  ('Перчатка не доказательство','leigh-hunt|the-glove-and-the-lions','Leigh Hunt','The Glove and the Lions','English','United Kingdom',1844,'https://en.wikisource.org/wiki/The_Poetical_Works_of_Leigh_Hunt/The_Glove_and_the_Lions','Автор умер в 1859 году; оригинал XIX века находится в public domain.','["Robert Schumann — Der Handschuh, Op. 87 (родственный сюжет Шиллера)"]','Женщина бросает перчатку к львам, чтобы проверить возлюбленного; он выполняет испытание и отвергает тщеславие.','Возвращённая перчатка','Не использовать насилие над животными, исторические имена и строки.'),
  ('Колокол под водой','robert-southey|the-inchcape-rock','Robert Southey','The Inchcape Rock','English','United Kingdom',1802,'https://en.wikisource.org/wiki/Poems_That_Every_Child_Should_Know/The_Inchcape_Rock','Автор умер в 1843 году; баллада 1802 года — public domain.','[]','Ровер снимает предупреждающий колокол с опасного рифа и позднее сам оказывается без сигнала.','Колокол под водой','Трагический финал заменяем ответственным исправлением поступка.'),
  ('Плыви, пока спят','oliver-wendell-holmes|the-ballad-of-the-oysterman','Oliver Wendell Holmes Sr.','The Ballad of the Oysterman','English','USA',1830,'https://en.wikisource.org/wiki/Page:The_Complete_Poetical_Works_of_Oliver_Wendell_Holmes_(1923).pdf/359','Автор умер в 1894 году; текст впервые опубликован в 1830 году и относится к public domain.','["Фольклорные песенные версии, зафиксированные в Minstrelsy of Maine"]','Устричник переплывает реку ради тайной встречи с дочерью рыбака.','Лунная вода между берегами','Не переносить трагикомический финал и строки оригинала.'),
  ('Экспедиция из ниоткуда','lewis-carroll|the-hunting-of-the-snark','Lewis Carroll','The Hunting of the Snark','English','United Kingdom',1876,'https://en.wikisource.org/wiki/The_Hunting_of_the_Snark_(1876)','Первое издание 1876 года и PD-статус подтверждены Wikisource; автор умер в 1898 году.','["Mike Batt — The Hunting of the Snark, концепт-альбом и сценическая версия"]','Эклектичная команда отправляется искать загадочного Снарка, несмотря на страхи и несовместимые привычки.','Карта без ориентиров','Не использовать неологизмы, персонажей и формулы Кэрролла.'),
  ('Своя минута','g-k-chesterton|the-donkey','G. K. Chesterton','The Donkey','English','United Kingdom',1927,'https://en.wikisource.org/wiki/The_Year%27s_at_the_Spring:_An_Anthology_of_Recent_Poetry/Chesterton,_G._K','Автор умер в 1936 году; произведение 1927 года находится в public domain в юрисдикциях life+70.','[]','Ослик, которого считают нелепым, помнит единственный момент общего признания.','Длинные уши на фоне аплодисментов','Не использовать религиозную рамку и строки оригинала.')
)
INSERT INTO public.song_idea_sources (idea_id, original_key, author_name, original_title, original_language, origin_country, original_year, source_url, rights_check, music_adaptations, source_synopsis, main_image, editorial_status, editor_note)
SELECT i.id, s.original_key, s.author_name, s.original_title, s.original_language, s.origin_country, s.original_year, s.source_url, s.rights_check, s.music_adaptations::jsonb, s.source_synopsis, s.main_image, 'accepted', s.editor_note
FROM sources s JOIN public.song_ideas i ON i.title = s.title
ON CONFLICT (original_key) DO NOTHING;
